        while q:
            cur = q.popleft()
            if arr[cur] == 0:
                return True
            if arr[cur] < 0:
                continue
            step = arr[cur]
            arr[cur] = -arr[cur]
            if cur + step < len(arr):
                q.append(cur + step)
            if cur - step >= 0:
                q.append(cur - step)
        return False

