class Solution {
    public int closedIsland(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean[][] vis = new boolean[m][n];
        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0 && !vis[i][j]) {
                    if (isClosed(grid, i, j, m, n, vis)) {
                        count++;
                    }
                }
            }
        }
        return count;
    }
    private boolean isClosed(int[][] g, int r, int c, int m, int n, boolean[][] vis) {
        if (r < 0 || r >= m || c < 0 || c >= n) return false;
        if (g[r][c] == 1 || vis[r][c]) return true;
        vis[r][c] = true;
        boolean up = isClosed(g, r - 1, c, m, n, vis);
        boolean down = isClosed(g, r + 1, c, m, n, vis);
        boolean left = isClosed(g, r, c - 1, m, n, vis);
        boolean right = isClosed(g, r, c + 1, m, n, vis);
        return up && down && left && right;
    }
}

