class Solution {
    public int countSubIslands(int[][] grid1, int[][] grid2) {
        int m = grid1.length, n = grid1[0].length;
        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid2[i][j] == 1) {
                    List<int[]> island = new ArrayList<>();
                    collect(grid2, i, j, island);
                    boolean isSub = true;
                    for (int[] cell : island) {
                        if (grid1[cell[0]][cell[1]] == 0) isSub = false;
                    }
                    if (isSub) count++;
                }
            }
        }
        return count;
    }
    private void collect(int[][] g, int r, int c, List<int[]> island) {
        if (r < 0 || r >= g.length || c < 0 || c >= g[0].length || g[r][c] == 0) return;
        g[r][c] = 0;
        island.add(new int[]{r, c});
        collect(g, r + 1, c, island);
        collect(g, r - 1, c, island);
        collect(g, r, c + 1, island);
        collect(g, r, c - 1, island);
    }
}

