class Solution {
    public int maxDistance(int[][] grid) {
        int n = grid.length;
        List<int[]> land = new ArrayList<>();
        List<int[]> water = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) land.add(new int[]{i, j});
                else water.add(new int[]{i, j});
            }
        }
        if (land.isEmpty() || water.isEmpty()) return -1;
        int maxDist = -1;
        for (int[] w : water) {
            int minDist = Integer.MAX_VALUE;
            for (int[] l : land) {
                minDist = Math.min(minDist, Math.abs(w[0] - l[0]) + Math.abs(w[1] - l[1]));
            }
            maxDist = Math.max(maxDist, minDist);
        }
        return maxDist;
    }
}

