class Solution {
    public int snakesAndLadders(int[][] board) {
        int n = board.length;
        int[] dist = new int[n * n + 1];
        Arrays.fill(dist, -1);
        Queue<Integer> q = new LinkedList<>();
        q.offer(1);
        dist[1] = 0;
        while (!q.isEmpty()) {
            int curr = q.poll();
            if (curr == n * n) return dist[curr];
            for (int i = 1; i <= 6 && curr + i <= n * n; i++) {
                int next = curr + i;
                int[] pos = getCoord(next, n);
                int dest = board[pos[0]][pos[1]] != -1 ? board[pos[0]][pos[1]] : next;
                if (dist[dest] == -1) {
                    dist[dest] = dist[curr] + 1;
                    q.offer(dest);
                }
            }
        }
        return -1;
    }
    private int[] getCoord(int s, int n) {
        int r = n - 1 - (s - 1) / n;
        int c = (s - 1) % n;
        if ((n - 1 - r) % 2 == 1) c = n - 1 - c;
        return new int[]{r, c};
    }
}

