class Solution {
    public int maximumDetonation(int[][] bombs) {
        int n = bombs.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < n; i++) {
            long r = bombs[i][2];
            long rSq = r * r;
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    long dx = bombs[i][0] - bombs[j][0];
                    long dy = bombs[i][1] - bombs[j][1];
                    if (dx * dx + dy * dy <= rSq) adj.get(i).add(j);
                }
            }
        }
        int max = 0;
        for (int i = 0; i < n; i++) {
            boolean[] vis = new boolean[n];
            max = Math.max(max, dfs(i, adj, vis));
        }
        return max;
    }
    private int dfs(int u, List<List<Integer>> adj, boolean[] vis) {
        vis[u] = true;
        int count = 1;
        for (int v : adj.get(u)) {
            if (!vis[v]) count += dfs(v, adj, vis);
        }
        return count;
    }
}

