class Solution {
    public int maximumDetonation(int[][] bombs) {
        int n = bombs.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < n; i++) {
            long r = (long) bombs[i][2] * bombs[i][2];
            long x1 = bombs[i][0], y1 = bombs[i][1];
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                long dx = x1 - bombs[j][0];
                long dy = y1 - bombs[j][1];
                if (dx * dx + dy * dy <= r) {
                    adj.get(i).add(j);
                }
            }
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            boolean[] vis = new boolean[n];
            ans = Math.max(ans, dfs(i, adj, vis));
        }
        return ans;
    }
    private int dfs(int u, List<List<Integer>> adj, boolean[] vis) {
        vis[u] = true;
        int count = 1;
        for (int v : adj.get(u)) {
            if (!vis[v]) {
                count += dfs(v, adj, vis);
            }
        }
        return count;
    }
}

